-- 05_P5_cmbo.sql — 콤보 5종(LOOKUP 원천 실측: SMS_MAIL_SEND_SYSTEM 15 / MAIL_SEND_CYCLE 8 / _DETAIL 132 / LANGUAGE 3)
-- 종속 콤보는 PARENT_CODE 를 함께 내려 FE 에서 cascade 필터(그리드 dataMap 원복 표준)

INSERT INTO SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT 'MailModule', 'DM', 'Mail Module', 'SELECT DISTINCT SEGMENT1 AS CODE, SEGMENT3 AS NAME, MIN(DISPLAY_SEQ) AS SORT_SEQ FROM SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL WHERE LOOKUP_TYPE = ''SMS_MAIL_SEND_SYSTEM'' AND VALID_YN = ''Y'' GROUP BY SEGMENT1, SEGMENT3 ORDER BY SORT_SEQ', 'Y', 'admin', SYSDATE, 'admin', SYSDATE FROM DUAL
 WHERE NOT EXISTS (SELECT 1 FROM SCM_ADM_CMBO_SQL_M WHERE SQL_ID = 'MailModule');
INSERT INTO SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT 'MailSubModule', 'DM', 'Mail Sub Module (Module 종속)', 'SELECT DISTINCT SEGMENT2 AS CODE, SEGMENT4 AS NAME, SEGMENT1 AS PARENT_CODE, MIN(DISPLAY_SEQ) AS SORT_SEQ FROM SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL WHERE LOOKUP_TYPE = ''SMS_MAIL_SEND_SYSTEM'' AND VALID_YN = ''Y'' GROUP BY SEGMENT2, SEGMENT4, SEGMENT1 ORDER BY SORT_SEQ', 'Y', 'admin', SYSDATE, 'admin', SYSDATE FROM DUAL
 WHERE NOT EXISTS (SELECT 1 FROM SCM_ADM_CMBO_SQL_M WHERE SQL_ID = 'MailSubModule');
INSERT INTO SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT 'MailSendCycle', 'DM', 'Mail Send Cycle (Main)', 'SELECT DISTINCT SEGMENT1 AS CODE, SEGMENT3 AS NAME, MIN(DISPLAY_SEQ) AS SORT_SEQ FROM SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL WHERE LOOKUP_TYPE = ''MAIL_SEND_CYCLE'' AND VALID_YN = ''Y'' GROUP BY SEGMENT1, SEGMENT3 ORDER BY SORT_SEQ', 'Y', 'admin', SYSDATE, 'admin', SYSDATE FROM DUAL
 WHERE NOT EXISTS (SELECT 1 FROM SCM_ADM_CMBO_SQL_M WHERE SQL_ID = 'MailSendCycle');
INSERT INTO SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT 'MailSendCycleDetail', 'DM', 'Mail Send Cycle Detail (Sub1~3, PARENT_CODE 종속)', 'SELECT DISTINCT SEGMENT2 AS CODE, SEGMENT3 AS NAME, SEGMENT1 AS PARENT_CODE, MIN(DISPLAY_SEQ) AS SORT_SEQ FROM SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL WHERE LOOKUP_TYPE = ''MAIL_SEND_CYCLE_DETAIL'' AND VALID_YN = ''Y'' GROUP BY SEGMENT2, SEGMENT3, SEGMENT1 ORDER BY SORT_SEQ', 'Y', 'admin', SYSDATE, 'admin', SYSDATE FROM DUAL
 WHERE NOT EXISTS (SELECT 1 FROM SCM_ADM_CMBO_SQL_M WHERE SQL_ID = 'MailSendCycleDetail');
INSERT INTO SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT 'MailLanguage', 'ALL', 'Mail Language', 'SELECT DISTINCT SEGMENT1 AS CODE, SEGMENT2 AS NAME, MIN(DISPLAY_SEQ) AS SORT_SEQ FROM SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL WHERE LOOKUP_TYPE = ''LANGUAGE'' AND VALID_YN = ''Y'' GROUP BY SEGMENT1, SEGMENT2 ORDER BY SORT_SEQ', 'Y', 'admin', SYSDATE, 'admin', SYSDATE FROM DUAL
 WHERE NOT EXISTS (SELECT 1 FROM SCM_ADM_CMBO_SQL_M WHERE SQL_ID = 'MailLanguage');

COMMIT;
